$('#resetQueue').addEventListener('click',()=>{const count=reviewedCount(),draftCount=Object.keys(reviewDrafts).length;openModal('Reset annotation progress',`<p>This will clear <b>${count} completed or escalated review${count===1?'':'s'}</b>, <b>${draftCount} saved draft${draftCount===1?'':'s'}</b>, and all saved decisions from this browser for the 100-item PT-100 queue. This cannot be undone.</p><p>Skipped items will also return to their original pending state. Tickets and checkout QA history will be kept.</p><button type="button" class="button button-dark" id="confirmResetQueue">Reset review progress</button>`);$('#modalDone').textContent='Cancel'});
function renderTickets(){
 const c=ticketCounts();
 const values={ticketActiveTotal:c.active,ticketNewTotal:c.new,ticketProgressTotal:c.inProgress,ticketBlockedTotal:c.blocked,ticketReviewTotal:c.inReview,ticketOverdueTotal:c.overdue,overviewOpenTicketCount:c.active,activeFilterCount:c.active,newFilterCount:c.new,triagedFilterCount:c.triaged,progressFilterCount:c.inProgress,blockedFilterCount:c.blocked,reviewFilterCount:c.inReview,closedFilterCount:c.closed,cancelledFilterCount:c.cancelled,overdueFilterCount:c.overdue,ticketNavCount:c.active};
 for(const [id,value] of Object.entries(values)){const node=$('#'+id);if(node)node.textContent=value}
 const labels={active:'Active tickets',new:'New tickets',triaged:'Triaged tickets',in_progress:'In progress',blocked:'Blocked tickets',in_review:'Awaiting review',closed:'Closed tickets',cancelled:'Cancelled tickets',overdue:'Overdue tickets'};
 const shown=TicketDomain.filterTickets(tickets,ticketFilter,ticketToday());$('#ticketListTitle').textContent=labels[ticketFilter]||'Active tickets';$('#ticketListCount').textContent=`${shown.length} ${shown.length===1?'ticket':'tickets'}`;
 if(!shown.some(t=>t.id===selectedTicket))selectedTicket=shown[0]?.id||null;
 $('#ticketList').innerHTML=shown.map(t=>`<button class="ticket-row ${selectedTicket===t.id?'active':''}" data-ticket-id="${escapeHtml(t.id)}"><span class="ticket-priority ${String(t.priority||'normal').toLowerCase()}"></span><span class="ticket-row-copy"><b>${escapeHtml(t.subject)}</b><small>${escapeHtml(t.id)} · ${escapeHtml(t.sku)} · ${escapeHtml(t.assignedTo)}</small><small class="${ticketIsOverdue(t)?'ticket-overdue':''}">${t.dueDate?`Due ${escapeHtml(t.dueDate)}${ticketIsOverdue(t)?' · OVERDUE':''}`:'No due date'}</small></span><span class="ticket-row-state ${t.status}">${ticketStatusLabel(t.status)}</span></button>`).join('')||'<div class="ticket-list-empty">No tickets in this view.</div>';
 const detail=$('#ticketDetail');detail.innerHTML=renderTicketDetail(tickets.find(t=>t.id===selectedTicket));
 $('#ticketList').querySelectorAll('[data-ticket-id]').forEach(b=>b.addEventListener('click',()=>{selectedTicket=b.dataset.ticketId;renderTickets()}));
 detail.querySelector('#applyCatalogCorrection')?.addEventListener('click',applyCatalogCorrection);detail.querySelectorAll('[data-ticket-transition]').forEach(b=>b.addEventListener('click',advanceTicketStatus));detail.querySelector('#openLinkedItem')?.addEventListener('click',openLinkedItem);detail.querySelector('#addTicketNote')?.addEventListener('click',addTicketNote);detail.querySelectorAll('[data-ticket-field]').forEach(el=>el.addEventListener('change',()=>updateTicketField(el)));detail.querySelectorAll('#resolutionInput,#blockerInput,#transitionNote,#reviewNoteInput').forEach(el=>el.addEventListener('input',updateTransitionValidity));updateTransitionValidity();
}
function ticketStatusLabel(status){return TicketDomain.LABELS[status]||'New'}
function renderTicketDetail(t){
 if(!t)return '<div class="ticket-empty"><span>▤</span><h2>No tickets in this view</h2><p>Choose another status filter or create a product operations ticket.</p></div>';
 const item=cosmeticProducts.find(p=>p.sku===t.sku),created=new Date(t.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
 const opt=(values,current)=>values.map(x=>`<option ${current===x?'selected':''}>${escapeHtml(x)}</option>`).join('');
 let actions='';
 if(t.status==='new')actions='<button class="button button-dark" data-ticket-transition="triaged">Complete triage</button><small>Set an accountable owner in ticket details first.</small><label class="ticket-form-label" for="transitionNote">Cancellation reason (20+ characters)</label><textarea id="transitionNote" rows="2" placeholder="Explain why this duplicate or invalid report is withdrawn."></textarea><button class="button button-quiet" data-ticket-transition="cancelled">Cancel ticket</button>';
 if(t.status==='triaged')actions='<button class="button button-dark" data-ticket-transition="in_progress">Accept and start work</button><label class="ticket-form-label" for="transitionNote">Cancellation reason (20+ characters)</label><textarea id="transitionNote" rows="2" placeholder="Explain why this report should be withdrawn."></textarea><button class="button button-quiet" data-ticket-transition="cancelled">Cancel ticket</button>';
 if(t.status==='in_progress')actions=`<label class="ticket-form-label" for="resolutionInput">Resolution summary (30+ characters)</label><textarea id="resolutionInput" rows="3" placeholder="State the change, source evidence and verification result.">${escapeHtml(t.resolutionSummary||'')}</textarea><div class="ticket-action-row"><button class="button button-dark" data-ticket-transition="in_review">Submit for review</button><button class="button button-quiet" data-ticket-transition="blocked">Mark blocked</button></div><label class="ticket-form-label" for="blockerInput">Blocker and dependency (20+ characters)</label><textarea id="blockerInput" rows="2" placeholder="What is needed, from whom, and by when?"></textarea>`;
 if(t.status==='blocked')actions=`<p class="ticket-transition-help"><b>Blocked:</b> ${escapeHtml(t.blockedReason||'No blocker detail recorded.')}</p><label class="ticket-form-label" for="transitionNote">Resume note (20+ characters)</label><textarea id="transitionNote" rows="2" placeholder="What changed to unblock the work?"></textarea><button class="button button-dark" data-ticket-transition="in_progress">Resume work</button>`;
 if(t.status==='in_review')actions=`<label class="ticket-form-label" for="reviewNoteInput">Reviewer decision note (20+ characters)</label><textarea id="reviewNoteInput" rows="3" placeholder="Verify the record and cite what you checked."></textarea><div class="ticket-action-row"><button class="button button-dark" data-ticket-transition="closed" data-review-decision="approve">Approve and close</button><button class="button button-quiet" data-ticket-transition="in_progress" data-review-decision="return">Return for changes</button></div>`;
 if(t.status==='closed')actions=`<label class="ticket-form-label" for="transitionNote">Reopen reason (20+ characters)</label><textarea id="transitionNote" rows="2" placeholder="Explain the remaining issue and needed work."></textarea><button class="button button-quiet" data-ticket-transition="in_progress">Reopen ticket</button>`;
 const correction=t.catalogField?`<section class="catalog-correction"><div class="correction-heading"><b>Field-level change record</b><span class="correction-state ${t.correctionApplied?'applied':''}">${t.correctionApplied?'Applied':'Pending'}</span></div><p><b>Field:</b> ${escapeHtml(catalogFieldLabel(t.catalogField))}</p><p><b>Before:</b> ${escapeHtml(t.observedValue||'Not captured')}</p><p><b>Proposed:</b> ${escapeHtml(t.proposedCorrection||'Not entered')}</p><p><b>Evidence:</b> ${escapeHtml(t.evidenceRef||'Not referenced')}</p>${t.status==='in_progress'?`<label for="correctionValue">Apply approved value</label><textarea id="correctionValue" rows="3">${escapeHtml(t.proposedCorrection||'')}</textarea><button class="button button-quiet" id="applyCatalogCorrection">${t.correctionApplied?'Update applied value':'Apply correction to linked product'}</button>`:''}${t.correctionAppliedAt?`<small>Applied ${escapeHtml(new Date(t.correctionAppliedAt).toLocaleString())}</small>`:''}</section>`:'';
 const controls=`<div class="ticket-controls"><label>Priority<select data-ticket-field="priority">${opt(['Urgent','High','Normal','Low'],t.priority)}</select></label><label>Impact<select data-ticket-field="impact">${opt(['Critical','High','Moderate','Low'],t.impact)}</select></label><label>Owner<select data-ticket-field="assignedTo">${opt(['Unassigned','trainee11','Catalog QA','ML Ops','Content Operations','Product Operations'],t.assignedTo)}</select></label><label>Due date<input type="date" data-ticket-field="dueDate" value="${escapeHtml(t.dueDate||'')}"></label><label>Workstream<select data-ticket-field="affectedProcess">${opt(['Product taxonomy','Image ingest','Catalog metadata','Claims and compliance','Checkout QA','Other operations'],t.affectedProcess)}</select></label><label>Evidence reference<input type="text" data-ticket-field="evidenceRef" maxlength="120" value="${escapeHtml(t.evidenceRef||'')}"></label></div>`;
 const activity=(t.activity||[]).map(e=>`<div><i></i><span><b>${escapeHtml(e.message||e)}</b>${e.by?` · ${escapeHtml(e.by)}`:''}${e.at?` · ${escapeHtml(new Date(e.at).toLocaleString())}`:''}</span></div>`).join('');
 return `<div class="ticket-detail-head"><div><div class="ticket-id-line"><span>${escapeHtml(t.id)}</span><span class="ticket-state ${t.status}">${ticketStatusLabel(t.status)}</span><span class="ticket-priority-label ${String(t.priority).toLowerCase()}">${escapeHtml(t.priority)} priority</span>${ticketIsOverdue(t)?'<span class="ticket-overdue">OVERDUE</span>':''}</div><h2>${escapeHtml(t.subject)}</h2><p>${escapeHtml(t.type)} · Opened ${created} by ${escapeHtml(t.createdBy||'Catalog QA')}</p></div><div class="ticket-transition-actions">${actions}</div></div>${controls}<div class="ticket-context"><div><span>LINKED RECORD</span><b>${escapeHtml(t.sku)}</b></div><div><span>PRODUCT</span><b>${escapeHtml(item?.variant||'Catalog item')}</b></div><div><span>QUEUE</span><b>PT-${cosmeticProducts.length}</b></div><button id="openLinkedItem">Open product record →</button></div><section class="ticket-description"><span>ISSUE SUMMARY</span><p>${escapeHtml(t.description)}</p><h3>Acceptance outcome</h3><p>${escapeHtml(t.expectedOutcome||'Not specified.')}</p><div class="ticket-triage-tags"><span>IMPACT: ${escapeHtml(t.impact||'Moderate')}</span><span>WORKSTREAM: ${escapeHtml(t.affectedProcess||'Catalog metadata')}</span><span>SOURCE: ${escapeHtml(t.evidenceRef||'Not cited')}</span></div></section>${correction}${t.blockedReason&&t.status!=='blocked'?`<p class="ticket-transition-help">Previous blocker: ${escapeHtml(t.blockedReason)}</p>`:''}${t.resolutionSummary?`<section class="ticket-resolution-record"><b>Resolution submitted</b><p>${escapeHtml(t.resolutionSummary)}</p>${t.reviewNote?`<p><b>Review note:</b> ${escapeHtml(t.reviewNote)}</p>`:''}</section>`:''}<section class="ticket-activity"><h3>Lifecycle history</h3>${activity||'<p>No activity has been recorded.</p>'}</section><section class="ticket-comments"><h3>Investigation notes <span>${(t.comments||[]).length}</span></h3><div class="ticket-comment-list">${(t.comments||[]).map(c=>`<article><b>${escapeHtml(c.by)}</b><time>${escapeHtml(c.at)}</time><p>${escapeHtml(c.text)}</p></article>`).join('')||'<p class="empty-comments">Add evidence or a clear handoff.</p>'}</div><label for="ticketNoteInput">Add an internal note (20+ characters)</label><textarea id="ticketNoteInput" rows="2" placeholder="Record a source check, decision or handoff."></textarea><button class="text-button" id="addTicketNote">Add investigation note</button></section><div class="ticket-resolution-note">Lifecycle: New → Triaged → In progress → In review → Closed. Blocked work resumes through a documented dependency; review may return work to the owner.</div>`;
}
function catalogFieldLabel(field){return ({name:'Product title',description:'Product description',ingredients:'Ingredients',suitability:'Suitability',claims:'Claims',directions:'Directions',netContent:'Net contents'})[field]||field}
function applyCatalogCorrection(){const t=tickets.find(x=>x.id===selectedTicket),input=$('#correctionValue');if(!t||t.status!=='in_progress'||!t.catalogField||!input)return;const value=input.value.trim();if(value.length<5){toast('Enter a specific corrected value before applying it.');return}const product=cosmeticProducts.find(p=>p.sku===t.sku);if(!product)return;catalogFixes[t.sku]=catalogFixes[t.sku]||{};catalogFixes[t.sku][t.catalogField]=value;product[t.catalogField]=value;t.proposedCorrection=value;t.correctionApplied=true;t.correctionAppliedAt=new Date().toISOString();persistCatalogFixes();saveTicketUpdate(t,`${catalogFieldLabel(t.catalogField)} correction applied to ${t.sku}`)}
function updateTransitionValidity(){const t=tickets.find(x=>x.id===selectedTicket);if(!t)return;const form=$('#ticketDetail');form?.querySelectorAll('[data-ticket-transition]').forEach(button=>{const next=button.dataset.ticketTransition;button.disabled=(next==='triaged'&&(!t.assignedTo||t.assignedTo==='Unassigned'))||(next==='in_review'&&($('#resolutionInput')?.value.trim().length<30||Boolean(t.catalogField&&!t.correctionApplied)))||(next==='blocked'&&$('#blockerInput')?.value.trim().length<20)||(next==='cancelled'&&$('#transitionNote')?.value.trim().length<20)||(['closed','in_progress'].includes(next)&&t.status==='in_review'&&$('#reviewNoteInput')?.value.trim().length<20)||(next==='in_progress'&&t.status==='blocked'&&$('#transitionNote')?.value.trim().length<20)||(next==='in_progress'&&t.status==='closed'&&$('#transitionNote')?.value.trim().length<20)})}
function saveTicketUpdate(t,message){logTicket(t,message);persistTickets();renderTickets();renderGoalProgress();toast(message)}
function updateTicketField(control){const t=tickets.find(x=>x.id===selectedTicket);if(!t)return;const field=control.dataset.ticketField,value=control.value;if(t[field]===value)return;t[field]=value;const label=field==='assignedTo'?'Assigned to':field==='priority'?'Priority set to':field==='impact'?'Impact set to':field==='affectedProcess'?'Affected process set to':field==='evidenceRef'?'Evidence reference set to':'Due date set to';saveTicketUpdate(t,`${label}: ${value||'not set'}`)}function advanceTicketStatus(e){const t=tickets.find(x=>x.id===selectedTicket);if(!t)return;const button=e.currentTarget,next=button.dataset.ticketTransition,note=$('#transitionNote')?.value.trim()||$('#reviewNoteInput')?.value.trim()||'';const context={note,resolutionSummary:$('#resolutionInput')?.value.trim()||'',decision:button.dataset.reviewDecision,};if(next==='blocked')context.note=$('#blockerInput')?.value.trim()||'';const actor=t.status==='in_review'?'Catalog QA':'trainee11';try{const updated=TicketDomain.transition(t,next,context,{now:new Date().toISOString(),by:actor});const i=tickets.findIndex(x=>x.id===t.id);tickets[i]=updated;ticketFilter=next==='closed'?'closed':next==='in_review'?'in_review':next==='blocked'?'blocked':next==='triaged'?'triaged':next==='cancelled'?'cancelled':'active';$$('#ticketFilters button').forEach(b=>b.classList.toggle('selected',b.dataset.ticketFilter===ticketFilter));saveTicketUpdate(updated,`Ticket moved to ${ticketStatusLabel(next)}`)}catch(error){toast(error.message)}}
function addTicketNote(){const t=tickets.find(x=>x.id===selectedTicket),field=$('#ticketNoteInput');if(!t||!field)return;const text=field.value.trim();if(text.length<20){toast('Write a useful note of at least 20 characters.');return}t.comments=t.comments||[];t.comments.push({by:'trainee11',at:ticketStamp(),text});saveTicketUpdate(t,'Internal note added')}
function openLinkedItem(){const t=tickets.find(x=>x.id===selectedTicket);if(!t)return;const i=cosmeticProducts.findIndex(p=>p.sku===t.sku);if(i>=0){currentIndex=i;navigate('annotation');renderWorkItem();updateWorkflowSteps()}}
$$('#ticketFilters button').forEach(b=>b.addEventListener('click',()=>{ticketFilter=b.dataset.ticketFilter;selectedTicket=tickets.find(ticketIsVisible)?.id||null;$$('#ticketFilters button').forEach(x=>x.classList.toggle('selected',x===b));renderTickets()}));
function openTicketForm(preselectedSku=cosmeticProducts[Math.max(0,currentIndex)]?.sku){
 const options=cosmeticProducts.map(p=>`<option value="${p.sku}" ${p.sku===preselectedSku?'selected':''}>${p.sku} · ${escapeHtml(p.variant)}</option>`).join('');
 openModal('Create workflow ticket',`<p>Record the affected SKU, exact field, observed value, proposed correction, evidence, owner, and acceptance condition. A correction ticket must be applied from the investigation workspace before resolution.</p>
 <label class="ticket-form-label" for="ticketType">Issue type</label><select id="ticketType"><option>Product text discrepancy</option><option>Taxonomy mismatch</option><option>Image quality</option><option>Product metadata conflict</option><option>Duplicate record</option><option>Packaging mismatch</option><option>Taxonomy gap</option><option>Claim or compliance review</option><option>Other catalog issue</option></select>
 <label class="ticket-form-label" for="ticketSku">Related product</label><select id="ticketSku">${options}</select>
 <label class="ticket-form-label" for="ticketCatalogField">Catalog field</label><select id="ticketCatalogField"><option value="">No field correction</option><option value="name">Product title</option><option value="description">Product description</option><option value="ingredients">Ingredients</option><option value="suitability">Suitability</option><option value="claims">Claims</option><option value="directions">Directions</option><option value="netContent">Net contents</option></select>
 <label class="ticket-form-label" for="ticketObservedValue">Observed value</label><textarea id="ticketObservedValue" rows="2" placeholder="Choose a field to load the current catalog value." readonly></textarea>
 <label class="ticket-form-label" for="ticketCorrection">Proposed correction</label><textarea id="ticketCorrection" rows="2" placeholder="Enter the supported replacement value."></textarea>
 <label class="ticket-form-label" for="ticketProcess">Affected work area</label><select id="ticketProcess"><option>Catalog metadata</option><option>Product taxonomy</option><option>Image ingest</option><option>Claims and compliance</option><option>Checkout QA</option><option>Other operations</option></select>
 <label class="ticket-form-label" for="ticketImpact">Business impact</label><select id="ticketImpact"><option>Moderate</option><option>Critical</option><option>High</option><option>Low</option></select>
 <label class="ticket-form-label" for="ticketPriority">Priority</label><select id="ticketPriority"><option>Normal</option><option>High</option><option>Urgent</option><option>Low</option></select>
 <label class="ticket-form-label" for="ticketAssignee">Assign to</label><select id="ticketAssignee"><option>Unassigned</option><option>trainee11</option><option>Catalog QA</option><option>ML Ops</option><option>Content Operations</option><option>Product Operations</option></select>
 <label class="ticket-form-label" for="ticketDueDate">Target due date</label><input id="ticketDueDate" type="date" min="${ticketToday()}"/>
 <label class="ticket-form-label" for="ticketEvidenceRef">Evidence reference</label><input id="ticketEvidenceRef" type="text" maxlength="120" placeholder="Supplier master, artwork panel, or source row"/>
 <label class="ticket-form-label" for="ticketSubject">Summary (12+ characters)</label><input id="ticketSubject" type="text" maxlength="100" placeholder="Specific, searchable issue summary"/>
 <label class="ticket-form-label" for="ticketDescription">Evidence and issue details (40+ characters)</label><textarea id="ticketDescription" rows="3" placeholder="What fields conflict, what evidence did you inspect, and why does it matter?"></textarea>
 <label class="ticket-form-label" for="ticketOutcome">Expected outcome (20+ characters)</label><textarea id="ticketOutcome" rows="2" placeholder="State what should be corrected and how it will be verified."></textarea>
 <button type="button" class="button button-dark ticket-create-button" id="createTicketSubmit" disabled>Create ticket</button>`);
 const sku=$('#ticketSku'),field=$('#ticketCatalogField'),observed=$('#ticketObservedValue');
 const loadObserved=()=>{const product=cosmeticProducts.find(p=>p.sku===sku.value);observed.value=field.value&&product?String(product[field.value]||''):''};
 const validate=()=>{const fieldChosen=Boolean(field.value),correctionReady=$('#ticketEvidenceRef').value.trim().length>=8&&(!fieldChosen||($('#ticketCorrection').value.trim().length>=5&&observed.value.trim().length>=5));$('#createTicketSubmit').disabled=$('#ticketSubject').value.trim().length<12||$('#ticketDescription').value.trim().length<40||$('#ticketOutcome').value.trim().length<20||!correctionReady};
 sku.addEventListener('change',()=>{loadObserved();validate()});field.addEventListener('change',()=>{loadObserved();validate()});
 ['ticketSubject','ticketDescription','ticketOutcome','ticketCorrection','ticketEvidenceRef'].forEach(id=>$('#'+id).addEventListener('input',validate));
}
function createTicket(){
 const draft={type:$('#ticketType').value,sku:$('#ticketSku').value,priority:$('#ticketPriority').value,impact:$('#ticketImpact').value,affectedProcess:$('#ticketProcess').value,evidenceRef:$('#ticketEvidenceRef').value.trim(),assignedTo:$('#ticketAssignee').value,dueDate:$('#ticketDueDate').value,description:$('#ticketDescription').value.trim(),subject:$('#ticketSubject').value.trim(),expectedOutcome:$('#ticketOutcome').value.trim(),catalogField:$('#ticketCatalogField').value,observedValue:$('#ticketObservedValue').value.trim(),proposedCorrection:$('#ticketCorrection').value.trim()};
 const errors=TicketDomain.validateDraft(draft);if(errors.length){toast(errors[0]);return}
  const ticket=TicketDomain.createTicket(draft,{id:TicketDomain.nextId(tickets),now:new Date().toISOString(),by:'trainee11'});tickets.unshift(ticket);persistTickets();recordWorkspaceEvent('ticket',`${ticket.id} created`,`${ticket.sku} · ${ticket.priority} priority · New`,'Recorded');selectedTicket=ticket.id;ticketFilter='new';$$('#ticketFilters button').forEach(b=>b.classList.toggle('selected',b.dataset.ticketFilter===ticketFilter));closeModal();navigate('tickets');toast(`${ticket.id} created in the New queue.`)
}
$('#openTicketBtn').addEventListener('click',()=>openTicketForm(cosmeticProducts[currentIndex]?.sku));$('#newTicketBtn').addEventListener('click',()=>openTicketForm());
$('#zoomBtn').addEventListener('click',()=>{$('.image-stage').classList.toggle('zoomed');$('#zoomBtn').innerHTML=$('.image-stage').classList.contains('zoomed')?'⌕ &nbsp;Fit image':'⌕ &nbsp;Zoom image'});

const modal=$('#modal');function openModal(title,html){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=html;$('#modalDone').textContent=title==='Create workflow ticket'?'Cancel':'Got it';modal.classList.add('open')}function closeModal(){modal.classList.remove('open');$('#modalDone').textContent='Got it'}$('#guidelinesBtn').addEventListener('click',()=>openModal('Product taxonomy guidelines',`<p>Review one catalog image at a time. Choose the most specific leaf category supported by the product’s intended use and visible packaging.</p><ul>${taxonomy.map(t=>`<li><b>${escapeHtml(t.path.split(' › ').at(-1))}:</b> examples include ${escapeHtml(t.variants.slice(0,2).join(' and ').toLowerCase())}.</li>`).join('')}<li>Escalate images with unclear product identity or conflicting catalog details.</li></ul><p>Model confidence describes the model proposal, not your confidence. Record your own confidence before submission.</p>`));$('#closeModal').addEventListener('click',closeModal);$('#modalDone').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal();if(e.target.closest('#createTicketSubmit'))createTicket();if(e.target.closest('#confirmResetQueue')){reviews={};reviewDrafts={};try{localStorage.removeItem(STORAGE_KEY);localStorage.removeItem(REVIEW_DRAFT_KEY)}catch{}currentIndex=nextPending(0);recordWorkspaceEvent('review','PT-100 review progress reset','Saved decisions and drafts cleared · tickets and QA history retained','Reset');closeModal();renderQueue();renderWorkItem();toast('Review decisions and drafts reset. Tickets and QA history were kept.')}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function downloadShiftHandoff(){
 const completed=reviewedCount(),draftCount=Object.keys(reviewDrafts).length,counts=ticketCounts(),active=tickets.filter(TicketDomain.isActive),qaRuns=(()=>{try{return JSON.parse(localStorage.getItem('meridian-qa-runs-pt100-v2')||'[]')}catch{return []}})();
 recordWorkspaceEvent('handoff','Shift handoff prepared',`${completed}/${cosmeticProducts.length} catalog items submitted · ${counts.active} active tickets`,'Exported');
 const lines=['MERIDIAN OPERATIONS WORKBENCH - SHIFT HANDOFF',`Prepared: ${new Date().toLocaleString()}`,'Workspace: Acme Retail · Catalog Intelligence','Assignment: PT-100 · Product taxonomy v3','Mode: Single-browser training demonstration','',`CATALOG REVIEW: ${completed}/${cosmeticProducts.length} submitted or escalated; ${cosmeticProducts.length-completed} outstanding; ${draftCount} saved drafts.`, `Escalations: ${Object.values(reviews).filter(r=>r.status==='escalated').length}; skipped: ${Object.values(reviews).filter(r=>r.status==='skipped').length}.`,'','TICKET QUEUE:',`Active ${counts.active} · New ${counts.new} · In progress ${counts.inProgress} · Blocked ${counts.blocked} · In review ${counts.inReview} · Overdue ${counts.overdue}.`];
 if(active.length)for(const t of active)lines.push(`- ${t.id} [${TicketDomain.LABELS[t.status]} / ${t.priority}] ${t.subject} | ${t.sku} | Owner: ${t.assignedTo||'Unassigned'} | Due: ${t.dueDate||'Not set'}${t.status==='blocked'?` | Blocker: ${t.blockedReason||'See ticket notes'}`:''}`);else lines.push('- No active tickets.');
 lines.push('','CHECKOUT QA:');if(qaRuns.length){for(const run of qaRuns.slice(0,3))lines.push(`- ${run.id}: ${run.passed}/${run.total} passed, ${run.failed} failed · ${run.time}`)}else lines.push('- No QA runs recorded.');
 lines.push('','RECENT WORKSPACE EVENTS:');for(const e of workspaceEvents().slice(0,12))lines.push(`- ${new Date(e.at).toLocaleString()} · ${e.title} · ${e.detail}`);
 lines.push('','All progress and this handoff file are local to this browser. No work was synchronized to a shared system.');
 const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`meridian-PT100-handoff-${ticketToday()}.txt`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Shift handoff downloaded for this browser session.');
}
$('#downloadHandoff').addEventListener('click',downloadShiftHandoff);
$('#openEventLog').addEventListener('click',()=>{const events=workspaceEvents();const content=events.length?`<p>Local activity history for this browser. The newest 50 events are retained.</p><ol class="event-log-list">${events.map(e=>`<li><b>${escapeHtml(e.title)}</b><small>${escapeHtml(e.detail)} · ${escapeHtml(new Date(e.at).toLocaleString())}</small></li>`).join('')}</ol>`:'<p>No workspace activity has been recorded yet.</p>';openModal('Workspace event log',content)});
try{const shiftKey=`meridian-shift-opened-${ticketToday()}`;if(!sessionStorage.getItem(shiftKey)){recordWorkspaceEvent('shift','Demo shift opened','PT-100 assignment · single-browser training workspace','Started');sessionStorage.setItem(shiftKey,'1')}}catch{}
renderQueue();renderWorkItem();updateWorkflowSteps();renderTickets();renderWorkspaceEvents();


